        for cL in range(3):
            for cR in range(3):
                if cL != cR:
                    dp_prev[cL][cR] = cost[0][cL] + cost[n-1][cR]
        # iterate remaining pairs
        for i in range(1, m):
            dp_cur = [[INF]*3 for _ in range(3)]
            for cl in range(3):
                for cr in range(3):
                    if cl == cr:
                        continue
                    cur_cost = cost[i][cl] + cost[n-1-i][cr]
                    for pl in range(3):
                        for pr in range(3):
                            if pl == pr:
                                continue
                            if pl == cl or pr == cr:
                                continue
                            val = dp_prev[pl][pr] + cur_cost
                            if val < dp_cur[cl][cr]:
                                dp_cur[cl][cr] = val
            dp_prev = dp_cur
        # answer is min over last pair
        ans = INF
        for cl in range(3):
            for cr in range(3):
                if cl != cr and dp_prev[cl][cr] < ans:
                    ans = dp_prev[cl][cr]
        return ans
