        if val_new(l)<val(l):
            if node.l is None:
                node.l=LiChaoNode(l,mid)
            self._add(node.l,m,b)
        elif val_new(r)<val(r):
            if node.r is None:
                node.r=LiChaoNode(mid+1,r)
            self._add(node.r,m,b)
    def query(self,x):
