class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold is irrelevant because it is at least 1.
        if not edges:
            return -1

        # Extract unique weights and sort
        weights = sorted({w for _, _, w in edges})
        # Build adjacency lists once for each weight threshold? We'll rebuild per check
        def can_reach(max_w: int) -> bool:
            rev_adj = [[] for _ in range(n)]
            for u, v, w in edges:
                if w <= max_w:
                    rev_adj[v].append(u)  # reverse edge
            q = deque([0])
            seen = [False] * n
            seen[0] = True
            while q:
                cur = q.popleft()
                for nxt in rev_adj[cur]:
                    if not seen[nxt]:
                        seen[nxt] = True
                        q.append(nxt)
            return all(seen)

        lo, hi = 0, len(weights) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can_reach(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
