        # Build reversed adjacency list
        adj = [[] for _ in range(n)]
        for a, b, w in edges:
            adj[b].append((a, w))  # reversed edge

        INF = 10**18
        dist = [INF] * n
        dist[0] = 0
        pq = [(0, 0)]  # (dist, node)

        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            for v, w in adj[u]:
                nd = max(d, w)
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

        maxw = 0
        for d in dist:
            if d == INF:
                return -1
            if d > maxw:
                maxw = d
        return maxw
