from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1
        seg = [-1] * (2 * size)
        # build leaves
        for i in range(n):
            seg[size + i] = baskets[i]
        # build internal nodes
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos: int, val: int):
            idx = size + pos
            seg[idx] = val
            idx >>= 1
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx >>= 1

        def query_first_ge(val: int) -> int:
            if seg[1] < val:
                return -1
            idx = 1
            while idx < size:
                if seg[2 * idx] >= val:
                    idx = 2 * idx
                else:
                    idx = 2 * idx + 1
            return idx - size

        unplaced = 0
        for f in fruits:
            pos = query_first_ge(f)
            if pos == -1:
                unplaced += 1
            else:
                update(pos, -1)  # mark as used
        return unplaced
