        for i in range(size-1,0,-1):
            seg[i] = max(seg[2*i], seg[2*i+1])
        used = [False]*n
        def query(val):
            if seg[1] < val:
                return -1
            idx = 1
            while idx < size:
                if seg[2*idx] >= val:
                    idx = 2*idx
                else:
                    idx = 2*idx+1
            pos = idx - size
            if pos >= n or used[pos]:
                return -1
            used[pos] = True
            seg[idx] = 0
            idx >>= 1
            while idx:
                seg[idx] = max(seg[2*idx], seg[2*idx+1])
                idx >>= 1
            return pos
        unplaced = 0
        for f in fruits:
            if query(f) == -1:
                unplaced += 1
        return unplaced
