class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        parent = list(range(n + 1))  # parent[n] is sentinel

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        unplaced = 0
        for f in fruits:
            idx = find(0)
            while idx < n and baskets[idx] < f:
                parent[idx] = find(idx + 1)  # skip this basket
                idx = find(idx)
            if idx == n:
                unplaced += 1
            else:
                parent[idx] = find(idx + 1)  # mark basket as used
        return unplaced
