class Solution:
    def numOfUnplacedFruits(self, fruits: list[int], baskets: list[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1
        seg = [0] * (2 * size)
        for i in range(n):
            seg[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(idx, val):
            i = size + idx
            seg[i] = val
            i >>= 1
            while i:
                seg[i] = max(seg[2 * i], seg[2 * i + 1])
                i >>= 1

        def query(val, node, l, r):
            if seg[node] < val:
                return -1
            if l == r:
                return l
            mid = (l + r) >> 1
            if seg[2 * node] >= val:
                return query(val, 2 * node, l, mid)
            return query(val, 2 * node + 1, mid + 1, r)

        unplaced = 0
        for f in fruits:
            idx = query(f, 1, 0, size - 1)
            if idx == -1 or idx >= n:
                unplaced += 1
            else:
                update(idx, -1)
        return unplaced
